import json, fnmatch, subprocess, os, sys
cfg = json.load(open('config/new-repo.json'))
files = subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard']).decode().split('\n')
files = [f for f in files if f and os.path.exists(f)]
def excl(n):
    if n in cfg['keep']: return False
    return any(fnmatch.fnmatch(n,p) for p in cfg['exclude']) or n in cfg['practice_only']
out = [f for f in files if not excl(f)]
print('exported', len(out), file=sys.stderr)
texts = {}
for f in out:
    try: texts[f] = open(f, encoding='utf-8').read()
    except Exception: texts[f] = ''
for f in sorted(out):
    base = os.path.basename(f)
    stem = os.path.splitext(base)[0]
    keys = {f, base}
    if stem not in ('main','README','Readme','.gitkeep','__init__'): keys.add(stem)
    refs = [g for g,t in texts.items() if g != f and any(k in t for k in keys)]
    # exclude refs only from scaffold-export.json / tests
    real = [g for g in refs if g not in ('config/scaffold-export.json',) and not g.startswith('tests/')]
    if not real:
        print(f"{f}\t refs={refs[:4]}")
EOF
