import json, fnmatch, subprocess, os, re
cfg = json.load(open('config/new-repo.json'))
files = [f for f in subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard']).decode().split('\n') if f and os.path.exists(f)]
def excl(n):
    if n in cfg['keep']: return False
    return any(fnmatch.fnmatch(n,p) for p in cfg['exclude'])
out=[f for f in files if not excl(f)]
records = json.load(open('config/records.json'))
rec = json.dumps(records)
pat = re.compile(r'(?<![\w./-])((?:docs|scripts|config|ansible|tests|webapp|infra|\.isuscope)/[\w./-]+\.(?:md|py|sh|json|yml|yaml|txt|toml|env|rs|js|html|sql|conf))')
seen={}
for f in out:
    if f=='config/scaffold-export.json': continue
    try: t=open(f,encoding='utf-8').read()
    except: continue
    for m in pat.finditer(t):
        p=m.group(1).rstrip('.')
        if '*' in p or '<' in p: continue
        if not os.path.exists(p):
            seen.setdefault(p,set()).add(f)
for p,s in sorted(seen.items()):
    tag = 'record' if p in rec else ''
    print(f"{p} [{tag}] <- {sorted(s)[:4]}")
EOF
